import { useSearchParams } from 'react-router-dom';
import type { State, Lesson, DrivingAdapter } from '@/lib/driving-school/types';
import type { DrivingFailureKind } from '@/lib/driving-school/cloud-adapter';
import { schoolDateTime, schoolTimeToUtc, rublesToKopecks, safeCsvCell } from '@/lib/driving-school/time';
import { linkedProgramVersion } from '@/lib/driving-school/program-version';
import './driving-school.css';
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type SyntheticEvent,
  type ReactNode,
} from 'react';
import {
  Home,
  CalendarDays,
  Users,
  Car,
  BookOpen,
  Wallet,
  Settings,
  CircleHelp,
  Plus,
  ArrowUpRight,
  Clock,
  Check,
  LogOut,
  ArrowLeft,
  Download,
  Printer,
  RefreshCw,
  type LucideIcon,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import {
  Sidebar,
  SidebarProvider,
  SidebarHeader,
  SidebarContent,
  SidebarFooter,
  SidebarTrigger,
  SidebarInset,
  useSidebar,
} from './sidebar';
import {
  Table,
  TableHeader,
  TableBody,
  TableRow,
  TableHead,
  TableCell,
} from '@/components/ui/table';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';

import type {
  Row,
  Kind,
  Entry,
  Question,
  WindowSlot,
} from '@/lib/driving-school/types';
// Keep the shared preview UI independent from the Cloud/Auth client at runtime.
// This discriminator only closes a loaded view; it never grants capability.
function failureKind(error: unknown): DrivingFailureKind | null {
  if(!(error instanceof Error)||!('kind' in error))return null;
  const kind=String(error.kind);
  return ['auth','permission','missing','context','network','unknown'].includes(kind)?kind as DrivingFailureKind:null;
}
function isDrivingAccessClosed(error: unknown): boolean {
  return ['auth','permission','missing','context'].includes(failureKind(error)||'');
}
type Field = {
  key: string;
  label: string;
  type?: string;
  value?: string;
  options?: { id: string; name: string }[];
  required?: boolean;
  hint?: string;
};
type Modal = {
  title: string;
  description?: string;
  fields: Field[];
  path: string;
  payload?: Record<string, unknown>;
  submit?: string;
  transform?: (x: Record<string, unknown>) => Record<string, unknown>;
};
const labels: Record<string, string> = {
  today: 'Сегодня',
  schedule: 'Расписание',
  students: 'Ученики',
  team: 'Команда и автомобили',
  learning: 'Обучение и выпуск',
  finance: 'Финансы',
  settings: 'Настройки',
  help: 'Помощь',
  documents: 'Документы',
};
const statusLabel: Record<string, string> = {
  booked: 'Запланировано',
  completed: 'Проведено',
  cancelled: 'Отменено',
  no_show: 'Неявка',
};
const hours = (m: number) =>
  `${Math.floor(m / 60)} ч${m % 60 ? ' ' + (m % 60) + ' мин' : ''}`;
const money = (k: number) =>
  new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB' }).format(
    k / 100,
  );
function Brand() {
  return (
    <div className="brand">
      <b>Σ</b>
      <span>
        СИНТАГМА<small>Автошколы</small>
      </span>
    </div>
  );
}
function Choice({
  label,
  options,
  value,
  onChange,
  required = true,
  name,
}: {
  name: string;
  label: string;
  options: { id: string; name: string }[];
  value: string;
  onChange: (s: string) => void;
  required?: boolean;
}) {
  return (
    <label>
      {label}
      <select name={name} value={value} onChange={e=>onChange(e.target.value)} required={required} className="choice">
        {!options.some(o=>o.id==='') && <option value="">Выберите…</option>}
        {options.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}
      </select>
    </label>
  );
}
function DataTable({
  columns,
  rows,
}: {
  columns: string[];
  rows: ReactNode[][];
}) {
  return rows.length ? (
    <Table>
      <TableHeader>
        <TableRow>
          {columns.map((c) => (
            <TableHead key={c}>{c}</TableHead>
          ))}
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((r, i) => (
          <TableRow key={i}>
            {r.map((c, j) => (
              <TableCell key={j}>{c}</TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  ) : (
    <div className="empty">
      <BookOpen />
      <h3>Здесь пока нет записей</h3>
      <p>Записей по выбранным условиям пока нет.</p>
    </div>
  );
}
function Nav({
  role,
  view,
  go,
}: {
  role: string;
  view: string;
  go: (v: string) => void;
}) {
  const { setOpenMobile } = useSidebar();
  const menu: [string, string, LucideIcon][] =
    role === 'student'
      ? [
          ['today', 'Главная', Home],
          ['schedule', 'Записаться', CalendarDays],
          ['learning', 'Моё обучение', BookOpen],
          ['documents', 'Документы', BookOpen],
        ]
      : role === 'instructor'
        ? [
            ['today', 'Мой день', Home],
            ['schedule', 'Расписание', CalendarDays],
            ['students', 'Мои ученики', Users],
          ]
        : [
            ['today', 'Сегодня', Home],
            ['schedule', 'Расписание', CalendarDays],
            ['students', 'Ученики', Users],
            ['team', 'Команда и автомобили', Car],
            ['learning', 'Обучение и выпуск', BookOpen],
            ['finance', 'Финансы', Wallet],
          ];
  const item = (key: string, name: string, Icon: LucideIcon) => (
    <Button
      key={key}
      variant="ghost"
      className={'nav-item ' + (view === key ? 'active' : '')}
      onClick={() => {
        go(key);
        setOpenMobile(false);
      }}
    >
      <Icon />
      <span>{name}</span>
    </Button>
  );
  return (
    <Sidebar collapsible="offcanvas">
      <SidebarHeader>
        <Brand />
        <span className="sidebar-label">РАБОЧИЙ КАБИНЕТ</span>
      </SidebarHeader>
      <SidebarContent>
        {menu.map(([k, n, I]) => item(k as string, n as string, I))}
      </SidebarContent>
      <SidebarFooter>
        {role === 'owner' && item('settings', 'Настройки', Settings)}
        {item('help', 'Помощь', CircleHelp)}
        <small className="muted local-note">
          Автошколы · Beta
        </small>
      </SidebarFooter>
    </Sidebar>
  );
}

export default function DrivingApp({adapter,onExit,preview=false}:{adapter:DrivingAdapter;onExit:()=>void;preview?:boolean}) {
  const [params,setParams]=useSearchParams();
  const [data, setData] = useState<State | null>(null),
    [loading, setLoading] = useState(true),
    [error, setError] = useState(''),
    [notice, setNotice] = useState(''),
    [saving, setBusy] = useState(false),
    [view, setView] = useState('today'),
    [studentId, setStudentId] = useState(''),
    [modal, setModal] = useState<Modal | null>(null),
    [form, setForm] = useState<Record<string, string>>({}),
    [search, setSearch] = useState(''),
    [day, setDay] = useState(''),
    [answers, setAnswers] = useState<Record<string, number[]>>({}),
    [inviteLink, setInviteLink] = useState('');
  const [accountReceipt,setAccountReceipt]=useState<{login:string|null;isExisting:boolean}|null>(null);
  const [readConfirmed,setReadConfirmed]=useState(false);
  const [loadContext,setLoadContext]=useState<DrivingAdapter|null>(null);
  const [dataAdapter,setDataAdapter]=useState<DrivingAdapter|null>(null);
  const busy=saving||!readConfirmed;
  const mounted=useRef(true);
  const requestVersion=useRef(0);
  const context=useRef({adapter,epoch:0,closed:false});
  // Adapter context changes must hide the preceding view before passive effects run.
  if(context.current.adapter!==adapter)context.current={adapter,epoch:context.current.epoch+1,closed:false};
  const isCurrent=(token:{adapter:DrivingAdapter;epoch:number})=>mounted.current
    &&context.current.adapter===token.adapter&&context.current.epoch===token.epoch&&!context.current.closed;
  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;requestVersion.current++;context.current.epoch++;};},[]);
  const purgeClosedContext=useCallback((failure:unknown)=>{
    context.current.closed=true;context.current.epoch++;requestVersion.current++;
    setData(null);setDataAdapter(null);setReadConfirmed(false);setLoading(false);setBusy(false);
    setModal(null);setForm({});setAnswers({});setStudentId('');setSearch('');setView('today');
    setInviteLink('');setAccountReceipt(null);setNotice('');
    setError(failure instanceof Error?failure.message:'Доступ к автошколе не подтверждён');
  },[]);
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 60000);
    return () => clearInterval(timer);
  }, []);
  const reload = useCallback(async () => {
    if(context.current.adapter!==adapter||!mounted.current)return null;
    if(context.current.closed){context.current.closed=false;context.current.epoch++;}
    const token={adapter,epoch:context.current.epoch};const request=++requestVersion.current;
    setLoadContext(adapter);setLoading(true);setReadConfirmed(false);setError('');
    try {
      const next=await adapter.load();
      if(!isCurrent(token)||request!==requestVersion.current)return null;
      setData(next);setDataAdapter(adapter);setReadConfirmed(true);return next;
    } catch(failure) {
      if(!isCurrent(token)||request!==requestVersion.current)return null;
      if(isDrivingAccessClosed(failure))purgeClosedContext(failure);
      else {setReadConfirmed(false);setError(failure instanceof Error?failure.message:'Не удалось обновить автошколу');}
      throw failure;
    } finally {if(isCurrent(token)&&request===requestVersion.current)setLoading(false);}
  }, [adapter,purgeClosedContext]);
  useEffect(()=>{
    setData(null);setDataAdapter(null);setReadConfirmed(false);setModal(null);setForm({});
    setInviteLink('');setAccountReceipt(null);setNotice('');setAnswers({});setStudentId('');
    void reload().catch(()=>{});
    return()=>{if(context.current.adapter===adapter)requestVersion.current++;};
  },[adapter,reload]);
  useEffect(()=>{
    const recheck=()=>{if(document.visibilityState==='visible')void reload().catch(()=>{});};
    window.addEventListener('focus',recheck);document.addEventListener('visibilitychange',recheck);
    return()=>{window.removeEventListener('focus',recheck);document.removeEventListener('visibilitychange',recheck);};
  },[reload]);
  useEffect(()=>{setView(params.get('view')||'today');setStudentId(params.get('student')||'');},[params]);
  function go(v:string,s=''){setView(v);setStudentId(s);setSearch('');const next=new URLSearchParams();next.set('view',v);if(s)next.set('student',s);setParams(next);}
  function open(m: Modal) {
    setModal(m);
    setForm(Object.fromEntries(m.fields.map((f) => [f.key, f.value || ''])));
    setError('');
  }
  async function act(
    path: string,
    payload: Record<string, unknown>,
    message = 'Сохранено',
  ) {
    if(!readConfirmed||dataAdapter!==adapter)throw new Error('Сначала подтвердите доступ кнопкой «Обновить данные». До обновления запись недоступна.');
    if(saving)throw new Error('Предыдущее сохранение ещё выполняется');
    const token={adapter,epoch:context.current.epoch};
    setBusy(true);
    setError('');
    setNotice('');
    try {
      if(!data)throw new Error('Данные школы не загружены');
      const out = await adapter.mutate(path,payload,data);
      if(!isCurrent(token))throw new Error('Контекст автошколы изменился. Повторите проверку доступа.');
      try {await reload();} catch(failure) {
        if(!isCurrent(token)||isDrivingAccessClosed(failure))throw failure;
        setError('Операция подтверждена сервером, но список не обновлён. Нажмите «Обновить данные» перед следующей записью.');
      }
      if(!isCurrent(token))throw new Error('Контекст автошколы изменился. Повторите проверку доступа.');
      setNotice(preview?message+' · только в памяти стенда':message);
      return out;
    } catch (e) {
      if(isCurrent(token)) {
        if(isDrivingAccessClosed(e))purgeClosedContext(e);
        else {if(failureKind(e)==='network')setReadConfirmed(false);setError((e as Error).message);}
      }
      throw e;
    } finally {
      if(isCurrent(token))setBusy(false);
    }
  }
  async function submit(e: SyntheticEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!modal) return;
    const token={adapter,epoch:context.current.epoch};
    try {
      const values = {
        ...modal.payload,
        ...form,
        ...Object.fromEntries(new FormData(e.currentTarget)),
      };
      const result=await act(modal.path, modal.transform ? modal.transform(values) : values,
        modal.payload?.accountMode==='existing'?'Запись ученика создана. В списке учеников нажмите «Создать приглашение» и передайте ссылку владельцу существующего аккаунта вашей организации.':'Сохранено');
      if(!isCurrent(token))return;
      if(result.account&&typeof result.account==='object'){const a=result.account as {login?:unknown;isExisting?:unknown};setAccountReceipt({login:typeof a.login==='string'?a.login:null,isExisting:a.isExisting===true});}
      setModal(null);
      setForm({});
    } catch (e) {
      if(isCurrent(token))setError((e as Error).message || 'Проверьте заполнение формы');
    }
  }
  if (loading||loadContext!==adapter) return <main className="driving-school-root loading"><Brand/><p>{preview?'Загружаем синтетический стенд…':'Загружаем автошколу…'}</p></main>;
  if (!data||dataAdapter!==adapter) return <main className="driving-school-root loading"><Brand/><div role="alert" className="error">{error||'Данные автошколы не загружены'}</div><Button onClick={()=>void reload().catch(()=>{})}>Повторить загрузку</Button><Button variant="outline" onClick={onExit}>Вернуться в СИНТАГМУ</Button></main>;
  const state = data;
  const owner = state.user.role === 'owner',
    canCreateStudents = owner && adapter.canCreateStudents===true,
    isStudent = state.user.role === 'student',
    settings = JSON.parse(state.school.settings),
    zone = settings.timezone;
  const localInput=(d:Date)=>schoolDateTime(d,zone);
  const todayDate=()=>schoolDateTime(Date.now(),zone).slice(0,10);
  const date = (n: number) =>
    new Intl.DateTimeFormat('ru-RU', {
      day: 'numeric',
      month: 'short',
      hour: '2-digit',
      minute: '2-digit',
      timeZone: zone,
    }).format(n);
  const time = (n: number) =>
    new Intl.DateTimeFormat('ru-RU', {
      hour: '2-digit',
      minute: '2-digit',
      timeZone: zone,
    }).format(n);
  const dateKey = (n: number) => schoolDateTime(n,zone).slice(0,10);
  const rows = <K extends Kind>(kind: K): Extract<Row, { kind: K }>[] =>
    state.resources.filter(
      (r): r is Extract<Row, { kind: K }> => r.kind === kind,
    );
  const name = (id: string | null | undefined) =>
    state.resources.find((r) => r.id === id)?.name || '—';
  const pick = <K extends Kind>(kind: K) => rows(kind).filter((r) => r.active);
  const currentStudent = isStudent
    ? rows('student').find(s=>s.id===state.user.resource_id)
    : rows('student').find((s) => s.id === studentId);
  const pending = state.lessons.filter(
    (l) => l.status === 'booked' && l.end < now,
  );
  const todays = state.lessons.filter(
    (l) => dateKey(l.start) === dateKey(now) && l.status !== 'cancelled',
  );
  async function inviteResource(resource: Row<'student' | 'instructor'>) {
    const token={adapter,epoch:context.current.epoch};
    try {
      const result=await act('invites',{resourceId:resource.id,resourceKind:resource.kind},'Приглашение создано');
      if(isCurrent(token))setInviteLink(typeof result.url==='string'?result.url:'');
    } catch { /* act keeps access errors and stale context private. */ }
  }
  function resourceForm(kind: Kind, studentAccountMode: 'new' | 'existing' = 'new') {
    const existingStudent=kind==='student'&&studentAccountMode==='existing';
    if(existingStudent&&!owner){setError('Приглашать учеников может только владелец автошколы');return;}
    if(kind==='student'&&!existingStudent&&!canCreateStudents){setError('В первом пилоте новых учеников добавляет владелец организации');return;}
    const fields: Field[] = [
      {
        key: 'name',
        label: kind === 'student' || kind === 'instructor' ? 'ФИО' : 'Название',
      },
    ];
    if (kind === 'program')
      fields.push(
        { key: 'version', label: 'Версия / дата утверждения' },
        {
          key: 'transmission',
          label: 'Трансмиссия',
          options: [
            { id: 'MT', name: 'Механика' },
            { id: 'AT', name: 'Автомат' },
          ],
          value: 'MT',
        },
        {
          key: 'practiceMinutes',
          label: 'План практики в минутах',
          type: 'number',
          hint: 'Укажите по программе школы. Это не универсальная законодательная норма.',
        },
      );
    if (kind === 'car')
      fields.push(
        { key: 'number', label: 'Государственный номер' },
        {
          key: 'transmission',
          label: 'Трансмиссия',
          options: [
            { id: 'MT', name: 'Механика' },
            { id: 'AT', name: 'Автомат' },
          ],
          value: 'MT',
        },
      );
    if (['student', 'group', 'course'].includes(kind))
      fields.push({
        key: 'programId',
        label: 'Программа',
        options: pick('program'),
      });
    if (kind === 'instructor')
      fields.push(
        { key: 'email', label: 'Email для входа существующего аккаунта', type: 'email', hint:'Должен совпасть с подтверждённым email учётной записи. Контактная почта может отличаться от него.' },
        { key: 'carId', label: 'Автомобиль', options: pick('car') },
      );
    if (kind === 'student') {
      if(!existingStudent)fields.push(
        {key:'password',label:'Начальный пароль для нового аккаунта СИНТАГМЫ',type:'password',hint:'Не менее 10 символов. У существующего ученика пароль не меняется. Письмо автоматически не отправляется.'},
      );
      fields.push(
        { key: 'email', label: existingStudent?'Email для входа существующего аккаунта':'Контактная почта (не логин)', type: 'email', hint:existingStudent?'Укажите email для входа в общий аккаунт вашей организации. Его принадлежность и подтверждение проверит сервер при принятии приглашения.':undefined },
        { key: 'phone', label: 'Телефон', required: false },
        {
          key: 'groupId',
          label: 'Группа (можно позже)',
          required: false,
          options: [{ id: '', name: 'Без группы' }, ...pick('group')],
        },
        {
          key: 'instructorId',
          label: 'Инструктор (можно позже)',
          required: false,
          options: [{ id: '', name: 'Назначить позже' }, ...pick('instructor')],
        },
      );
    }
    open({
      title: existingStudent?'Пригласить существующий аккаунт':(
        {
          student: 'Добавить ученика',
          group: 'Создать группу',
          program: 'Создать программу',
          car: 'Добавить автомобиль',
          instructor: 'Добавить инструктора',
        } as Record<string, string>
      )[kind],
      description:existingStudent?'Для существующего аккаунта вашей организации. Создаётся только запись ученика автошколы: общий аккаунт и его личные данные не меняются. Затем в списке учеников создайте одноразовую ссылку. Привязка появится только после принятия приглашения этим аккаунтом; письмо не отправляется.':kind==='student'?'Ученик создаётся штатной регистрацией СИНТАГМЫ с проверкой лимита и сразу получает привязку к автошколе. После сохранения будет показан логин для общего входа «По логину». Контактная почта не является логином.':kind==='program'||kind==='car'?'Первый пилот поддерживает категорию B. Для другой категории подключение ещё не подготовлено.':kind==='instructor'?'Создаётся запись инструктора, без новой учётной записи и без глобальной роли организации. Приглашение доступно для действующего общего аккаунта этой организации; новая организация при регистрации не подходит.':undefined,
      fields,
      path: 'resources',
      payload: existingStudent?{kind,accountMode:'existing'}:{kind},
      submit: existingStudent?'Создать запись для приглашения':undefined,
    });
  }
  function book(sid = '', start = '', end = '') {
    const s = rows('student').find(
      (r) => r.id === (sid || state.user.resource_id),
    );
    const i = rows('instructor').find((r) => r.id === s?.data.instructorId);
    open({
      title: 'Записать на вождение',
      description:
        'Время вводится и отображается в часовом поясе автошколы: ' +
        zone,
      fields: [
        {
          key: 'studentId',
          label: 'Ученик',
          options: pick('student'),
          value: s?.id,
        },
        {
          key: 'instructorId',
          label: 'Назначенный инструктор',
          options: pick('instructor'),
          value: i?.id,
        },
        {
          key: 'carId',
          label: 'Автомобиль инструктора',
          options: pick('car'),
          value: i?.data.carId,
        },
        { key: 'start', label: 'Начало', type: 'datetime-local', value: start },
        { key: 'end', label: 'Окончание', type: 'datetime-local', value: end },
      ],
      path: 'lessons',
      transform: (b) => ({
        ...b,
        start: schoolTimeToUtc(String(b.start),zone),
        end: schoolTimeToUtc(String(b.end),zone),
      }),
    });
  }
  function lessonAction(l: Lesson, action: string) {
    if (action === 'reschedule') {
      open({
        title: 'Перенести занятие',
        description:
